-- Student questionnaire templates (2026-10-25), after
-- 20261025_questionnaires_tables_and_functions.sql.
--
-- ── Templates ───────────────────────────────────────────────────────────
-- Seeded from "Core Competency Reflecting Brainstorm" (Nov 2024): one
-- activity per grade per reporting period. "Draw" prompts are written as
-- "write" for the phone form. Re-running updates them in place.
insert into public.questionnaire_template (id, kind, grade, period, year, title, theme, core_heading, myed_comment, questions)
values ('core-8-1', 'core_reflection', 8, 1, 2026, 'November Reflection', 'Self-Awareness and Goal Setting', 'Self-Awareness', 'We are pleased to highlight the Core Competencies as an integral part of our curriculum in British Columbia. Your student has reflected on the Core Competency of Self-Awareness and has given thought to self-awareness and goal setting. You are encouraged to speak with your student about their self-reflection.', '[{"prompt": "My Personal Shield: write one word or symbol for each.", "kind": "short_set", "options": {"labels": ["A strength", "An interest", "A goal", "Something that is me"]}}, {"prompt": "How can these help you do well this year?", "kind": "text"}, {"prompt": "How confident do you feel?", "kind": "scale4", "core_ids": ["PAR", "PPI"], "options": {"steps": ["Beginning", "Growing", "Confident", "Leading"], "why": "Why?"}}]'::jsonb)
on conflict (id) do update set kind = excluded.kind, grade = excluded.grade, period = excluded.period,
  year = excluded.year, title = excluded.title, theme = excluded.theme, core_heading = excluded.core_heading,
  myed_comment = excluded.myed_comment, questions = excluded.questions, updated_at = now();
insert into public.questionnaire_template (id, kind, grade, period, year, title, theme, core_heading, myed_comment, questions)
values ('core-8-2', 'core_reflection', 8, 2, 2026, 'March Reflection', 'Growth in Communication Skills', 'Communication and Thinking', 'We are pleased to highlight the Core Competencies as an integral part of our curriculum in British Columbia. Your student has reflected on the Core Competency of Communication and Thinking and has given thought to growth in communication skills. You are encouraged to speak with your student about their self-reflection.', '[{"prompt": "Describe a recent time you had to communicate clearly with someone.", "kind": "text"}, {"prompt": "What went well, and what could you do better next time?", "kind": "text"}, {"prompt": "How confident do you feel?", "kind": "scale4", "core_ids": ["COM"], "options": {"steps": ["Beginning", "Growing", "Confident", "Leading"], "why": "Why?"}}]'::jsonb)
on conflict (id) do update set kind = excluded.kind, grade = excluded.grade, period = excluded.period,
  year = excluded.year, title = excluded.title, theme = excluded.theme, core_heading = excluded.core_heading,
  myed_comment = excluded.myed_comment, questions = excluded.questions, updated_at = now();
